import{t as e}from"./api-CP2skCHa.js";var t={getAllReviews:t=>e.get(`/api/reviews`,{params:t}),createReview:t=>{if(t instanceof FormData)return e.post(`/api/reviews`,t);console.warn(`createReview: 建议直接传递 FormData 对象以支持图片上传`);let n=new FormData;return n.append(`review`,new Blob([JSON.stringify(t)],{type:`application/json`})),e.post(`/api/reviews`,n)},getDishReviews:(t,n)=>e.get(`/api/reviews/dish/${t}`,{params:n}),getUserReviews:(t,n)=>e.get(`/api/reviews/user/${t}`,{params:n}),getOrderReviews:t=>e.get(`/api/reviews/order/${t}`),getReview:t=>e.get(`/api/reviews/${t}`),updateReview:(t,n)=>{if(n instanceof FormData)return e.put(`/api/reviews/${t}`,n);console.warn(`updateReview: 建议直接传递 FormData 对象以支持图片上传`);let r=new FormData;return r.append(`review`,new Blob([JSON.stringify(n)],{type:`application/json`})),e.put(`/api/reviews/${t}`,r)},deleteReview:t=>e.delete(`/api/reviews/${t}`),replyToReview:(t,n)=>e.post(`/api/reviews/${t}/reply`,{reply:n}),updateReviewStatus:(t,n)=>e.put(`/api/reviews/${t}/status`,{status:n}),getReviewStats:t=>e.get(`/api/reviews/stats/${t}`),getPopularTags:(t=20)=>e.get(`/api/reviews/tags/popular`,{params:{limit:t}})};export{t};